1	/**
2	 * Format parsers. Each parser turns a raw file body into a normalised
3	 * `TestRun`. Two formats are supported:
4	 *
5	 *   - JSON  (`parseJsonResults`)  — a flexible, hand-friendly schema.
6	 *   - JUnit (`parseJUnitXml`)      — the de-facto CI interchange format.
7	 *
8	 * `parseResultFile` dispatches on file extension. All parsers throw an `Error`
9	 * with a message that names the offending source so the CLI can report which
10	 * file is bad.
11	 */
12	import type { TestCaseResult, TestRun, TestStatus } from "./types";
13	
14	/**
15	 * Normalise the many spellings a status can take across tools into our small
16	 * three-value set. JUnit-style `error` and JSON's `fail`/`failure` all collapse
17	 * into `failed`; `pending`/`ignored`/`disabled` collapse into `skipped`.
18	 */
19	export function normaliseStatus(raw: string): TestStatus {
20	  const s = raw.trim().toLowerCase();
21	  switch (s) {
22	    case "pass":
23	    case "passed":
24	    case "success":
25	    case "ok":
26	      return "passed";
27	    case "fail":
28	    case "failed":
29	    case "failure":
30	    case "error":
31	    case "errored":
32	      return "failed";
33	    case "skip":
34	    case "skipped":
35	    case "pending":
36	    case "ignored":
37	    case "disabled":
38	      return "skipped";
39	    default:
40	      throw new Error(`unrecognised test status: "${raw}"`);
41	  }
42	}
43	
44	/** Coerce an unknown duration field (seconds) into a finite, non-negative number. */
45	function coerceDuration(value: unknown): number {
46	  if (value === undefined || value === null) return 0;
47	  const n = typeof value === "number" ? value : Number(value);
48	  if (!Number.isFinite(n) || n < 0) return 0;
49	  return n;
50	}
51	
52	interface RawJsonTest {
53	  name?: unknown;
54	  suite?: unknown;
55	  classname?: unknown;
56	  status?: unknown;
57	  result?: unknown;
58	  outcome?: unknown;
59	  duration?: unknown;
60	  time?: unknown;
61	  message?: unknown;
62	}
63	
64	/**
65	 * Parse a JSON results file. Accepted shapes:
66	 *
67	 *   { "name": "...", "tests": [ {name,status,...}, ... ] }   // object form
68	 *   [ {name,status,...}, ... ]                               // bare array form
69	 *
70	 * Per-test fields: `name` (required), `suite`/`classname` (optional), one of
71	 * `status`/`result`/`outcome` (required), `duration`/`time` (optional seconds),
72	 * and `message` (optional).
73	 */
74	export function parseJsonResults(body: string, source: string): TestRun {
75	  let parsed: unknown;
76	  try {
77	    parsed = JSON.parse(body);
78	  } catch (err) {
79	    const reason = err instanceof Error ? err.message : String(err);
80	    throw new Error(`invalid JSON in "${source}": ${reason}`);
81	  }
82	
83	  // Accept either the object form (with a `tests` array) or a bare array.
84	  let runName = "";
85	  let rawTests: unknown;
86	  if (Array.isArray(parsed)) {
87	    rawTests = parsed;
88	  } else if (parsed && typeof parsed === "object") {
89	    const obj = parsed as { name?: unknown; tests?: unknown; testcases?: unknown };
90	    runName = typeof obj.name === "string" ? obj.name : "";
91	    rawTests = obj.tests ?? obj.testcases;
92	  }
93	
94	  if (!Array.isArray(rawTests)) {
95	    throw new Error(
96	      `invalid JSON in "${source}": expected a "tests" array or a top-level array of tests`,
97	    );
98	  }
99	
100	  const cases: TestCaseResult[] = rawTests.map((entry, index) => {
101	    if (!entry || typeof entry !== "object") {
102	      throw new Error(`invalid test entry at index ${index} in "${source}": not an object`);
103	    }
104	    const t = entry as RawJsonTest;
105	
106	    if (typeof t.name !== "string" || t.name.length === 0) {
107	      throw new Error(`test at index ${index} in "${source}" is missing a string "name"`);
108	    }
109	
110	    const rawStatus = t.status ?? t.result ?? t.outcome;
111	    if (typeof rawStatus !== "string") {
112	      throw new Error(`test "${t.name}" in "${source}" is missing a "status"`);
113	    }
114	
115	    const suite =
116	      typeof t.suite === "string" ? t.suite : typeof t.classname === "string" ? t.classname : "";
117	
118	    const result: TestCaseResult = {
119	      name: t.name,
120	      suite,
121	      status: normaliseStatus(rawStatus),
122	      durationSeconds: coerceDuration(t.duration ?? t.time),
123	    };
124	    if (typeof t.message === "string" && t.message.length > 0) {
125	      result.message = t.message;
126	    }
127	    return result;
128	  });
129	
130	  return { source, name: runName, cases };
131	}
132	
133	/* ----------------------------------------------------------------------------
134	 * Minimal XML parser
135	 *
136	 * Bun has no built-in XML parser and pulling a dependency would mean a network
137	 * install inside the CI container, so we ship a small, self-contained recursive
138	 * parser. It is deliberately scoped to what JUnit needs — elements, attributes,
139	 * text, CDATA, comments, the XML declaration, and the five predefined entities
140	 * (plus numeric character references). It is strict enough to reject malformed
141	 * input (mismatched/unclosed tags) so corrupt files surface as errors.
142	 * ------------------------------------------------------------------------- */
143	
144	/** A parsed XML element. `text` holds the element's own concatenated text. */
145	export interface XmlNode {
146	  tag: string;
147	  attrs: Record<string, string>;
148	  children: XmlNode[];
149	  text: string;
150	}
151	
152	/** Decode the predefined XML entities and numeric character references. */
153	function decodeEntities(s: string): string {
154	  return s.replace(/&(#x[0-9a-fA-F]+|#[0-9]+|[a-zA-Z]+);/g, (match, body: string) => {
155	    if (body[0] === "#") {
156	      const code = body[1] === "x" ? parseInt(body.slice(2), 16) : parseInt(body.slice(1), 10);
157	      return Number.isFinite(code) ? String.fromCodePoint(code) : match;
158	    }
159	    switch (body) {
160	      case "lt":
161	        return "<";
162	      case "gt":
163	        return ">";
164	      case "amp":
165	        return "&";
166	      case "quot":
167	        return '"';
168	      case "apos":
169	        return "'";
170	      default:
171	        return match; // leave unknown entities untouched
172	    }
173	  });
174	}
175	
176	/** Parse a start/self-closing tag beginning at `xml[start] === "<"`. */
177	function parseStartTag(
178	  xml: string,
179	  start: number,
180	): { node: XmlNode; next: number; selfClosing: boolean } {
181	  let i = start + 1;
182	  const len = xml.length;
183	
184	  // Tag name: up to whitespace, "/", or ">".
185	  const nameStart = i;
186	  while (i < len && !/[\s/>]/.test(xml[i] as string)) i++;
187	  const tag = xml.slice(nameStart, i);
188	  if (tag.length === 0) throw new Error(`malformed tag at offset ${start}`);
189	
190	  const attrs: Record<string, string> = {};
191	  while (i < len) {
192	    while (i < len && /\s/.test(xml[i] as string)) i++; // skip whitespace
193	    if (i >= len) throw new Error(`unterminated tag <${tag}>`);
194	    if (xml[i] === "/" && xml[i + 1] === ">") {
195	      return { node: { tag, attrs, children: [], text: "" }, next: i + 2, selfClosing: true };
196	    }
197	    if (xml[i] === ">") {
198	      return { node: { tag, attrs, children: [], text: "" }, next: i + 1, selfClosing: false };
199	    }
200	
201	    // Attribute name.
202	    const attrNameStart = i;
203	    while (i < len && !/[\s=/>]/.test(xml[i] as string)) i++;
204	    const attrName = xml.slice(attrNameStart, i);
205	    if (attrName.length === 0) throw new Error(`malformed attribute in <${tag}>`);
206	
207	    while (i < len && /\s/.test(xml[i] as string)) i++;
208	    let value = "";
209	    if (xml[i] === "=") {
210	      i++;
211	      while (i < len && /\s/.test(xml[i] as string)) i++;
212	      const quote = xml[i];
213	      if (quote !== '"' && quote !== "'") {
214	        throw new Error(`expected quoted value for attribute "${attrName}" in <${tag}>`);
215	      }
216	      i++;
217	      const valueStart = i;
218	      while (i < len && xml[i] !== quote) i++;
219	      if (i >= len) throw new Error(`unterminated attribute value in <${tag}>`);
220	      value = decodeEntities(xml.slice(valueStart, i));
221	      i++; // consume closing quote
222	    }
223	    attrs[attrName] = value;
224	  }
225	  throw new Error(`unterminated tag <${tag}>`);
226	}
227	
228	/** Parse a complete XML document into its single root element. */
229	export function parseXml(xml: string): XmlNode {
230	  const len = xml.length;
231	  let i = 0;
232	  let root: XmlNode | null = null;
233	  const stack: XmlNode[] = [];
234	
235	  const appendText = (raw: string): void => {
236	    const top = stack[stack.length - 1];
237	    if (top) top.text += raw;
238	  };
239	
240	  while (i < len) {
241	    if (xml[i] === "<") {
242	      if (xml.startsWith("<!--", i)) {
243	        const end = xml.indexOf("-->", i + 4);
244	        if (end === -1) throw new Error("unterminated comment");
245	        i = end + 3;
246	      } else if (xml.startsWith("<![CDATA[", i)) {
247	        const end = xml.indexOf("]]>", i + 9);
248	        if (end === -1) throw new Error("unterminated CDATA section");
249	        appendText(xml.slice(i + 9, end)); // CDATA content is verbatim, no decoding
250	        i = end + 3;
251	      } else if (xml.startsWith("<?", i)) {
252	        const end = xml.indexOf("?>", i + 2);
253	        if (end === -1) throw new Error("unterminated processing instruction");
254	        i = end + 2;
255	      } else if (xml.startsWith("<!", i)) {
256	        // DOCTYPE or similar declaration — skip to the matching ">".
257	        const end = xml.indexOf(">", i + 2);
258	        if (end === -1) throw new Error("unterminated declaration");
259	        i = end + 1;
260	      } else if (xml[i + 1] === "/") {
261	        // Closing tag.
262	        const end = xml.indexOf(">", i + 2);
263	        if (end === -1) throw new Error("unterminated closing tag");
264	        const tag = xml.slice(i + 2, end).trim();
265	        const open = stack.pop();
266	        if (!open) throw new Error(`unexpected closing tag </${tag}>`);
267	        if (open.tag !== tag) {
268	          throw new Error(`mismatched closing tag: expected </${open.tag}> but found </${tag}>`);
269	        }
270	        i = end + 1;
271	      } else {
272	        // Opening (possibly self-closing) tag.
273	        const { node, next, selfClosing } = parseStartTag(xml, i);
274	        const parent = stack[stack.length - 1];
275	        if (parent) {
276	          parent.children.push(node);
277	        } else if (root) {
278	          throw new Error(`multiple root elements (<${root.tag}> and <${node.tag}>)`);
279	        } else {
280	          root = node;
281	        }
282	        if (!selfClosing) stack.push(node);
283	        i = next;
284	      }
285	    } else {
286	      const next = xml.indexOf("<", i);
287	      const end = next === -1 ? len : next;
288	      const chunk = xml.slice(i, end);
289	      if (chunk.trim().length > 0) appendText(decodeEntities(chunk));
290	      i = end;
291	    }
292	  }
293	
294	  if (stack.length > 0) {
295	    throw new Error(`unclosed tag <${stack[stack.length - 1]?.tag}>`);
296	  }
297	  if (!root) throw new Error("no root element found");
298	  return root;
299	}
300	
301	/** Depth-first collect every descendant (and self) whose tag matches. */
302	function collectByTag(node: XmlNode, tag: string, out: XmlNode[] = []): XmlNode[] {
303	  if (node.tag === tag) out.push(node);
304	  for (const child of node.children) collectByTag(child, tag, out);
305	  return out;
306	}
307	
308	/**
309	 * Parse a JUnit XML document. Handles both a `<testsuites>` wrapper and a bare
310	 * `<testsuite>` root, arbitrarily nested suites, and the standard
311	 * failure/error/skipped child markers.
312	 */
313	export function parseJUnitXml(body: string, source: string): TestRun {
314	  let root: XmlNode;
315	  try {
316	    root = parseXml(body);
317	  } catch (err) {
318	    const reason = err instanceof Error ? err.message : String(err);
319	    throw new Error(`invalid XML in "${source}": ${reason}`);
320	  }
321	
322	  // A run name, if the document gives us one.
323	  const runName = root.attrs.name ?? "";
324	  const suites = collectByTag(root, "testsuite");
325	  // A lone <testsuite> root is itself a suite; collectByTag already includes it.
326	  // A <testsuites> wrapper contributes only its descendant <testsuite> nodes.
327	
328	  const cases: TestCaseResult[] = [];
329	  for (const suite of suites) {
330	    const suiteName = suite.attrs.name ?? "";
331	    // Only direct <testcase> children, so nested suites are not double-counted.
332	    for (const tc of suite.children.filter((c) => c.tag === "testcase")) {
333	      const name = tc.attrs.name ?? "";
334	      const className = tc.attrs.classname ?? "";
335	      const suiteLabel = className.length > 0 ? className : suiteName;
336	
337	      const failureNode = tc.children.find((c) => c.tag === "failure" || c.tag === "error");
338	      const skippedNode = tc.children.find((c) => c.tag === "skipped");
339	
340	      let status: TestStatus;
341	      let message: string | undefined;
342	      if (failureNode) {
343	        status = "failed";
344	        const attrMsg = failureNode.attrs.message;
345	        message = attrMsg && attrMsg.length > 0 ? attrMsg : failureNode.text.trim() || undefined;
346	      } else if (skippedNode) {
347	        status = "skipped";
348	        const attrMsg = skippedNode.attrs.message;
349	        if (attrMsg && attrMsg.length > 0) message = attrMsg;
350	      } else {
351	        status = "passed";
352	      }
353	
354	      const result: TestCaseResult = {
355	        name,
356	        suite: suiteLabel,
357	        status,
358	        durationSeconds: coerceDuration(tc.attrs.time),
359	      };
360	      if (message) result.message = message;
361	      cases.push(result);
362	    }
363	  }
364	
365	  return { source, name: runName, cases };
366	}
367	
368	/**
369	 * Parse a result file, dispatching on its extension. `.json` -> JSON format,
370	 * `.xml` (and `.junit`) -> JUnit XML. Unknown extensions raise a clear error.
371	 */
372	export function parseResultFile(body: string, source: string): TestRun {
373	  const lower = source.toLowerCase();
374	  if (lower.endsWith(".json")) return parseJsonResults(body, source);
375	  if (lower.endsWith(".xml") || lower.endsWith(".junit")) return parseJUnitXml(body, source);
376	  throw new Error(
377	    `cannot determine format for "${source}": expected a .json or .xml (JUnit) file`,
378	  );
379	}
