1	/**
2	 * Aggregation layer. Given the normalised runs from the parsers, compute the
3	 * matrix-wide totals and identify flaky tests.
4	 *
5	 * Flaky == a test that passed in at least one run and failed in at least one
6	 * other run. Skips never make a test flaky on their own; flakiness is strictly
7	 * about an inconsistent pass/fail verdict.
8	 */
9	import type { AggregateResult, FlakyTest, RunSummary, TestRun } from "./types";
10	
11	/**
12	 * Round to milliseconds. Summing floating-point seconds accumulates tiny
13	 * representation errors (0.1 + 0.2 === 0.30000000000000004); rounding the
14	 * accumulated totals to 3 decimals keeps the reported numbers clean and
15	 * deterministic without affecting any real-world precision.
16	 */
17	function roundMillis(seconds: number): number {
18	  return Math.round(seconds * 1000) / 1000;
19	}
20	
21	/** Stable cross-run identity for a test case. */
22	function testKey(suite: string, name: string): string {
23	  return `${suite}::${name}`;
24	}
25	
26	/** Per-test tally accumulated while scanning every run. */
27	interface Tally {
28	  name: string;
29	  suite: string;
30	  passed: number;
31	  failed: number;
32	  skipped: number;
33	  appearances: number;
34	}
35	
36	/**
37	 * Aggregate the supplied runs. Returns matrix-wide totals, the flaky-test list
38	 * (sorted most-failures-first, then by key for stable output), a per-run
39	 * summary in input order, and the overall pass/fail verdict.
40	 */
41	export function aggregate(runs: TestRun[]): AggregateResult {
42	  let passed = 0;
43	  let failed = 0;
44	  let skipped = 0;
45	  let total = 0;
46	  let durationSeconds = 0;
47	
48	  const tallies = new Map<string, Tally>();
49	  const runSummaries: RunSummary[] = [];
50	
51	  for (const r of runs) {
52	    let runPassed = 0;
53	    let runFailed = 0;
54	    let runSkipped = 0;
55	    let runDuration = 0;
56	
57	    for (const c of r.cases) {
58	      total++;
59	      durationSeconds += c.durationSeconds;
60	      runDuration += c.durationSeconds;
61	
62	      if (c.status === "passed") {
63	        passed++;
64	        runPassed++;
65	      } else if (c.status === "failed") {
66	        failed++;
67	        runFailed++;
68	      } else {
69	        skipped++;
70	        runSkipped++;
71	      }
72	
73	      const key = testKey(c.suite, c.name);
74	      let tally = tallies.get(key);
75	      if (!tally) {
76	        tally = { name: c.name, suite: c.suite, passed: 0, failed: 0, skipped: 0, appearances: 0 };
77	        tallies.set(key, tally);
78	      }
79	      tally.appearances++;
80	      if (c.status === "passed") tally.passed++;
81	      else if (c.status === "failed") tally.failed++;
82	      else tally.skipped++;
83	    }
84	
85	    runSummaries.push({
86	      source: r.source,
87	      name: r.name,
88	      passed: runPassed,
89	      failed: runFailed,
90	      skipped: runSkipped,
91	      durationSeconds: roundMillis(runDuration),
92	    });
93	  }
94	
95	  const flaky: FlakyTest[] = [];
96	  for (const [key, tally] of tallies) {
97	    // The defining condition: passed somewhere AND failed somewhere.
98	    if (tally.passed > 0 && tally.failed > 0) {
99	      flaky.push({
100	        key,
101	        name: tally.name,
102	        suite: tally.suite,
103	        passed: tally.passed,
104	        failed: tally.failed,
105	        skipped: tally.skipped,
106	        appearances: tally.appearances,
107	      });
108	    }
109	  }
110	  // Most-failing tests first; ties broken by key for deterministic ordering.
111	  flaky.sort((a, b) => b.failed - a.failed || a.key.localeCompare(b.key));
112	
113	  return {
114	    totals: {
115	      passed,
116	      failed,
117	      skipped,
118	      total,
119	      durationSeconds: roundMillis(durationSeconds),
120	    },
121	    flaky,
122	    runCount: runs.length,
123	    runs: runSummaries,
124	    passed: failed === 0,
125	  };
126	}
