1	/**
2	 * Markdown renderer for the GitHub Actions job summary.
3	 *
4	 * The output is intentionally plain (no emoji, GitHub-Flavoured-Markdown
5	 * tables) so it renders cleanly in a job summary AND so its exact lines are
6	 * easy to assert on from the act-driven integration tests. Numeric columns are
7	 * right-aligned with `---:`.
8	 */
9	import type { AggregateResult } from "./types";
10	
11	/** Format a duration in seconds as a fixed, 3-decimal value with a unit. */
12	export function formatDuration(seconds: number): string {
13	  return `${seconds.toFixed(3)}s`;
14	}
15	
16	/** Escape the pipe character so test names never break a table cell. */
17	function escapeCell(value: string): string {
18	  return value.replace(/\|/g, "\\|");
19	}
20	
21	/** Prefer the run's declared name; fall back to its source path. */
22	function runLabel(name: string, source: string): string {
23	  return name.length > 0 ? name : source;
24	}
25	
26	/**
27	 * Render the full aggregate result as a markdown document suitable for
28	 * `$GITHUB_STEP_SUMMARY`.
29	 */
30	export function renderMarkdown(result: AggregateResult): string {
31	  const { totals, flaky, runs } = result;
32	  const status = result.passed ? "PASSED" : "FAILED";
33	  const lines: string[] = [];
34	
35	  // --- Heading + one-line verdict -----------------------------------------
36	  lines.push("## Test Results Summary");
37	  lines.push("");
38	  lines.push(
39	    `**Result:** ${status} — ${totals.passed} passed, ${totals.failed} failed, ` +
40	      `${totals.skipped} skipped (${totals.total} total) across ${result.runCount} ` +
41	      `run${result.runCount === 1 ? "" : "s"} in ${formatDuration(totals.durationSeconds)}.`,
42	  );
43	  lines.push("");
44	
45	  // --- Totals table -------------------------------------------------------
46	  lines.push("| Metric | Count |");
47	  lines.push("| --- | ---: |");
48	  lines.push(`| Passed | ${totals.passed} |`);
49	  lines.push(`| Failed | ${totals.failed} |`);
50	  lines.push(`| Skipped | ${totals.skipped} |`);
51	  lines.push(`| Total | ${totals.total} |`);
52	  lines.push(`| Duration | ${formatDuration(totals.durationSeconds)} |`);
53	  lines.push("");
54	
55	  // --- Flaky tests --------------------------------------------------------
56	  if (flaky.length === 0) {
57	    lines.push("No flaky tests detected.");
58	  } else {
59	    lines.push(`### Flaky Tests (${flaky.length})`);
60	    lines.push("");
61	    lines.push("These tests passed in some runs and failed in others:");
62	    lines.push("");
63	    lines.push("| Test | Passed | Failed | Runs |");
64	    lines.push("| --- | ---: | ---: | ---: |");
65	    for (const f of flaky) {
66	      lines.push(`| ${escapeCell(f.key)} | ${f.passed} | ${f.failed} | ${f.appearances} |`);
67	    }
68	  }
69	  lines.push("");
70	
71	  // --- Per-run breakdown --------------------------------------------------
72	  lines.push("### Per-Run Breakdown");
73	  lines.push("");
74	  lines.push("| Run | Passed | Failed | Skipped | Duration |");
75	  lines.push("| --- | ---: | ---: | ---: | ---: |");
76	  for (const r of runs) {
77	    lines.push(
78	      `| ${escapeCell(runLabel(r.name, r.source))} | ${r.passed} | ${r.failed} | ` +
79	        `${r.skipped} | ${formatDuration(r.durationSeconds)} |`,
80	    );
81	  }
82	  lines.push("");
83	
84	  return lines.join("\n");
85	}
