1	#!/usr/bin/env bun
2	/**
3	 * Command-line entry point for the test-results aggregator.
4	 *
5	 * Usage:
6	 *   bun run src/cli.ts <file-or-dir> [<file-or-dir> ...] [options]
7	 *
8	 * Options:
9	 *   --fail-on-failure   exit 1 when any test failed (default: exit 0; this is a
10	 *                       reporting tool, so by default it never fails the build)
11	 *   --json              also print the full aggregate as JSON to stdout
12	 *   --help, -h          show usage
13	 *
14	 * Behaviour:
15	 *   - Directories are expanded to their `.json` and `.xml` result files.
16	 *   - The markdown report is appended to `$GITHUB_STEP_SUMMARY` when that
17	 *     environment variable is set (the GitHub Actions job summary), and is
18	 *     always echoed to stdout so it appears in the workflow logs.
19	 *   - A machine-readable `AGGREGATE ...` summary line is printed for easy
20	 *     assertion, and key=value pairs are appended to `$GITHUB_OUTPUT`.
21	 */
22	import { appendFile, readdir, stat } from "node:fs/promises";
23	import { join } from "node:path";
24	import { aggregate } from "./aggregate";
25	import { formatDuration, renderMarkdown } from "./markdown";
26	import { parseResultFile } from "./parsers";
27	import type { AggregateResult, TestRun } from "./types";
28	
29	/** Parsed command-line options. */
30	export interface CliOptions {
31	  paths: string[];
32	  failOnFailure: boolean;
33	  json: boolean;
34	  help: boolean;
35	}
36	
37	const USAGE = `test-results-aggregator
38	
39	Aggregate JUnit XML and JSON test result files across a matrix build, compute
40	totals, detect flaky tests, and render a markdown job summary.
41	
42	Usage:
43	  bun run src/cli.ts <file-or-dir> [<file-or-dir> ...] [options]
44	
45	Options:
46	  --fail-on-failure   Exit 1 if any test failed (default: always exit 0).
47	  --json              Also print the full aggregate result as JSON.
48	  -h, --help          Show this help.`;
49	
50	/** Parse argv (already sliced past the runtime + script). Throws on unknown flags. */
51	export function parseArgs(argv: string[]): CliOptions {
52	  const opts: CliOptions = { paths: [], failOnFailure: false, json: false, help: false };
53	  for (const arg of argv) {
54	    switch (arg) {
55	      case "--fail-on-failure":
56	        opts.failOnFailure = true;
57	        break;
58	      case "--json":
59	        opts.json = true;
60	        break;
61	      case "-h":
62	      case "--help":
63	        opts.help = true;
64	        break;
65	      default:
66	        if (arg.startsWith("-")) {
67	          throw new Error(`unknown option: ${arg}`);
68	        }
69	        opts.paths.push(arg);
70	    }
71	  }
72	  return opts;
73	}
74	
75	/** True when a path looks like a result file we can parse. */
76	function isResultFile(path: string): boolean {
77	  return /\.(json|xml|junit)$/i.test(path);
78	}
79	
80	/**
81	 * Expand the provided paths into a concrete, sorted list of result files.
82	 * Directories are searched recursively; explicit file paths pass through.
83	 * A non-existent path raises an error naming the path.
84	 */
85	export async function collectInputFiles(paths: string[]): Promise<string[]> {
86	  const files = new Set<string>();
87	  for (const p of paths) {
88	    let info;
89	    try {
90	      info = await stat(p);
91	    } catch {
92	      throw new Error(`path not found: ${p}`);
93	    }
94	    if (info.isDirectory()) {
95	      const entries = await readdir(p, { recursive: true });
96	      for (const entry of entries) {
97	        if (isResultFile(entry)) files.add(join(p, entry));
98	      }
99	    } else {
100	      files.add(p);
101	    }
102	  }
103	  return [...files].sort();
104	}
105	
106	/** Read and parse every file into a normalised run. */
107	export async function loadRuns(files: string[]): Promise<TestRun[]> {
108	  const runs: TestRun[] = [];
109	  for (const file of files) {
110	    const body = await Bun.file(file).text();
111	    runs.push(parseResultFile(body, file));
112	  }
113	  return runs;
114	}
115	
116	/** A compact, stable, machine-readable one-liner for log assertions. */
117	export function formatSummaryLine(result: AggregateResult): string {
118	  const t = result.totals;
119	  return (
120	    `AGGREGATE status=${result.passed ? "PASSED" : "FAILED"} ` +
121	    `passed=${t.passed} failed=${t.failed} skipped=${t.skipped} total=${t.total} ` +
122	    `duration=${formatDuration(t.durationSeconds)} flaky=${result.flaky.length} runs=${result.runCount}`
123	  );
124	}
125	
126	/** Build the `key=value` block appended to `$GITHUB_OUTPUT`. */
127	function formatGithubOutputs(result: AggregateResult): string {
128	  const t = result.totals;
129	  return (
130	    [
131	      `status=${result.passed ? "passed" : "failed"}`,
132	      `passed=${t.passed}`,
133	      `failed=${t.failed}`,
134	      `skipped=${t.skipped}`,
135	      `total=${t.total}`,
136	      `duration_seconds=${t.durationSeconds}`,
137	      `flaky=${result.flaky.length}`,
138	      `runs=${result.runCount}`,
139	    ].join("\n") + "\n"
140	  );
141	}
142	
143	/**
144	 * Program body. Returns the intended process exit code so it stays testable.
145	 *   0 — success (default, even with test failures present)
146	 *   1 — failures present and --fail-on-failure was given
147	 *   2 — usage / input error
148	 */
149	export async function main(argv: string[]): Promise<number> {
150	  let opts: CliOptions;
151	  try {
152	    opts = parseArgs(argv);
153	  } catch (err) {
154	    console.error(`error: ${err instanceof Error ? err.message : String(err)}`);
155	    console.error(USAGE);
156	    return 2;
157	  }
158	
159	  if (opts.help) {
160	    console.log(USAGE);
161	    return 0;
162	  }
163	
164	  if (opts.paths.length === 0) {
165	    console.error("error: no input paths given");
166	    console.error(USAGE);
167	    return 2;
168	  }
169	
170	  let files: string[];
171	  try {
172	    files = await collectInputFiles(opts.paths);
173	  } catch (err) {
174	    console.error(`error: ${err instanceof Error ? err.message : String(err)}`);
175	    return 2;
176	  }
177	
178	  if (files.length === 0) {
179	    console.error("error: no .json or .xml result files found in the given path(s)");
180	    return 2;
181	  }
182	
183	  let runs: TestRun[];
184	  try {
185	    runs = await loadRuns(files);
186	  } catch (err) {
187	    console.error(`error: ${err instanceof Error ? err.message : String(err)}`);
188	    return 2;
189	  }
190	
191	  const result = aggregate(runs);
192	  const markdown = renderMarkdown(result);
193	
194	  // Write the markdown to the GitHub Actions job summary, if available.
195	  const summaryPath = process.env.GITHUB_STEP_SUMMARY;
196	  if (summaryPath && summaryPath.length > 0) {
197	    try {
198	      await appendFile(summaryPath, markdown + "\n");
199	    } catch (err) {
200	      console.error(
201	        `warning: could not write job summary: ${err instanceof Error ? err.message : String(err)}`,
202	      );
203	    }
204	  }
205	
206	  // Always echo the report and the machine summary line to stdout.
207	  console.log(markdown);
208	  console.log(formatSummaryLine(result));
209	
210	  // Expose key numbers as step outputs for downstream steps.
211	  const outputPath = process.env.GITHUB_OUTPUT;
212	  if (outputPath && outputPath.length > 0) {
213	    try {
214	      await appendFile(outputPath, formatGithubOutputs(result));
215	    } catch (err) {
216	      console.error(
217	        `warning: could not write step outputs: ${err instanceof Error ? err.message : String(err)}`,
218	      );
219	    }
220	  }
221	
222	  if (opts.json) {
223	    console.log(JSON.stringify(result, null, 2));
224	  }
225	
226	  return opts.failOnFailure && !result.passed ? 1 : 0;
227	}
228	
229	// Only run when executed directly (not when imported by tests).
230	if (import.meta.main) {
231	  process.exit(await main(process.argv.slice(2)));
232	}
