1	/**
2	 * Shared type definitions for the test-results aggregator.
3	 *
4	 * Two on-disk formats (JUnit XML and JSON) are normalised into the same
5	 * internal model (`TestRun` / `TestCaseResult`) so the aggregation, flaky
6	 * detection, and markdown rendering layers never have to care which format a
7	 * result originally came from.
8	 */
9	
10	/**
11	 * The normalised outcome of a single test. JUnit's `<error>` is folded into
12	 * `failed` (an errored test did not pass), and the JSON format's various
13	 * spellings ("fail", "error", ...) normalise here too. Keeping the normalised
14	 * status set this small keeps flaky detection unambiguous: a test is flaky when
15	 * it is sometimes `passed` and sometimes `failed`.
16	 */
17	export type TestStatus = "passed" | "failed" | "skipped";
18	
19	/** A single normalised test case from one run. */
20	export interface TestCaseResult {
21	  /** The test's own name (the JUnit `name` attr or the JSON `name` field). */
22	  name: string;
23	  /** Owning suite/class. Falls back to "" when the source provides none. */
24	  suite: string;
25	  /** Normalised outcome. */
26	  status: TestStatus;
27	  /** Execution time in seconds (0 when the source omits it). */
28	  durationSeconds: number;
29	  /** Optional failure/error message, when the source provides one. */
30	  message?: string;
31	}
32	
33	/**
34	 * One result file == one "run" (one leg of a matrix build). `source` is the
35	 * file path or other identifier the run came from, used in error messages and
36	 * the markdown breakdown.
37	 */
38	export interface TestRun {
39	  /** Identifier for this run (typically the file path). */
40	  source: string;
41	  /** Optional human-readable run/suite name from the file. */
42	  name: string;
43	  /** All test cases recorded in this run. */
44	  cases: TestCaseResult[];
45	}
46	
47	/** Aggregate totals across every run. */
48	export interface Totals {
49	  passed: number;
50	  failed: number;
51	  skipped: number;
52	  /** passed + failed + skipped, i.e. total test executions across all runs. */
53	  total: number;
54	  /** Sum of every case's duration, in seconds. */
55	  durationSeconds: number;
56	}
57	
58	/**
59	 * A test that did not produce a consistent verdict across the runs it appeared
60	 * in: it passed at least once and failed at least once. This is the classic
61	 * "flaky" signal for a matrix build.
62	 */
63	export interface FlakyTest {
64	  /** Stable identity used to correlate the test across runs (`suite::name`). */
65	  key: string;
66	  name: string;
67	  suite: string;
68	  /** Number of runs in which this test passed. */
69	  passed: number;
70	  /** Number of runs in which this test failed. */
71	  failed: number;
72	  /** Number of runs in which this test was skipped. */
73	  skipped: number;
74	  /** Total number of runs this test appeared in. */
75	  appearances: number;
76	}
77	
78	/** The full aggregation result handed to the renderer. */
79	export interface AggregateResult {
80	  totals: Totals;
81	  /** Flaky tests, sorted most-failed-first then by name for determinism. */
82	  flaky: FlakyTest[];
83	  /** Number of result files / runs aggregated. */
84	  runCount: number;
85	  /** Per-run summary, in input order, for the markdown breakdown. */
86	  runs: RunSummary[];
87	  /** Overall verdict: true when there were zero failures. */
88	  passed: boolean;
89	}
90	
91	/** Compact per-run summary used in the markdown "per run" table. */
92	export interface RunSummary {
93	  source: string;
94	  name: string;
95	  passed: number;
96	  failed: number;
97	  skipped: number;
98	  durationSeconds: number;
99	}
